// The shell: the top pane, navigation, the date picker, the zoom, the sync line, and which view
// the big calendar window holds. The filter lives in the panel with the settings.
import { getConfig, getKV, setKV, queuedCount } from '../shared/store.js';
import { pull, drain } from '../shared/github.js';
import {
  loadModel, todayKey, addDays, addMonths, partsOf, monthGrid, weekStartOf, isoWeek, setZone,
  sprintRange, sprintOf
} from './data.js';
import {
  S, $, el, phone, dayLabel, icon, weekLetters, currentSprint, openPop, closePops
} from './ui.js';
import { renderView, wireView, openDayPop } from './views.js';
import { renderKanban } from './kanban.js';
import { closePopup } from './popup.js';
import { openPanel, renderFilter } from './settings.js';
import { loadPrefs, applyTheme, weekdayName } from '../shared/prefs.js';

let pick = { mode: 'days', y: 2026, m: 0, base: 0 };

// ---- rendering -----------------------------------------------------------------------------

function render() {
  const k = S.view.mode === 'K';
  $('#period-label').textContent = periodLabel();

  // One slot carries the way to the other kind of view. The board is not a zoom step, which is
  // why it has a slot of its own rather than a place in the cycle the label walks.
  $('#board').replaceChildren(icon(k ? 'cal' : 'board'));
  $('#board').setAttribute('aria-label', k ? 'Back to the month view' : 'Kanban');
  $('#period').setAttribute('aria-label', k ? 'Pick a sprint' : 'Pick a date');

  if (k) renderKanban($('#view'));
  else renderView($('#view'));
  renderZoom();
  renderFilter();
}

// The pane has to fit a phone, so every label is short. The month name is the device locale's
// abbreviation, upper-cased - short beats English.
const shortMonth = key => new Date(`${key}T12:00:00`)
  .toLocaleDateString(undefined, { month: 'short' }).replace(/\./g, '').toUpperCase();

function periodLabel() {
  const { mode, anchor } = S.view;
  const [y, , d] = partsOf(anchor);
  if (mode === 'D')
    return `${weekdayName(anchor, 'short').slice(0, 2).toUpperCase()} ${d}/${shortMonth(anchor)}`;
  if (mode === 'W') {
    // The ISO number is in the label whether or not the gutter is on, and the month is the one
    // the row's fourth day is in - the rule the gutter uses, so the two cannot disagree.
    const a = weekStartOf(anchor, S.prefs.weekStart);
    return `W${isoWeek(addDays(a, 3))}/${shortMonth(addDays(a, 3))}`;
  }
  if (mode === 'M') return `${shortMonth(anchor)}/${String(y).slice(2)}`;
  if (mode === 'Y') return String(y);
  return String(S.view.sprint);
}

// ---- the zoom ------------------------------------------------------------------------------
// A magnifier beside the view switch, offering what the view it was opened in can do and nothing
// else: the four periods in a calendar view, the board's two orientations on the board. It
// replaces the label's old cycle, which asked up to three taps to reach a view and never said
// which one you were in.

const PERIODS = [['D', 'day'], ['W', 'week'], ['M', 'month'], ['Y', 'year']];
const ORIENTS = [['vert', 'vertical'], ['horz', 'horizontal']];

function renderZoom() {
  const board = S.view.mode === 'K';
  const rows = board
    ? ORIENTS.map(([v, text]) => [v, text, S.prefs.boardOrientation === v, setOrientation])
    : PERIODS.map(([v, text]) => [v, text, S.view.mode === v, setMode]);
  $('#zoom-body').replaceChildren(...rows.map(([v, text, on, pick]) => {
    const b = el('button', `zrow${on ? ' on' : ''}`);
    b.type = 'button';
    b.setAttribute('aria-pressed', String(on));
    b.append(el('span', 'dot'), el('span', '', text));
    b.addEventListener('click', () => pick(v));
    return b;
  }));
}

function setMode(mode) {
  S.view.mode = mode;
  closePops();
  render();
}

// Remembered per device: it is a preference about this screen, like confirm discard. The
// calendar's own zoom is not - the app opens on the month, on today, as it always has.
async function setOrientation(v) {
  S.prefs.boardOrientation = v;
  await setKV('calendar.boardOrientation', v);
  S.view.col = 0;
  closePops();
  render();
}

$('#zoom-btn').addEventListener('click', () => {
  if (!$('#zoom-pop').hidden) return closePops();
  closePops();
  renderZoom();
  openPop($('#zoom-pop'), $('#zoom-btn'));
});

// ---- navigation ----------------------------------------------------------------------------

$('#board').addEventListener('click', () => {
  if (S.view.mode === 'K') S.view.mode = 'M';
  else {
    S.view.mode = 'K';
    S.view.sprint = sprintOf(S.view.anchor, S.model.settings) || currentSprint();
  }
  closePops();
  render();
});

function step(dir) {
  const v = S.view;
  if (v.mode === 'D') v.anchor = addDays(v.anchor, dir);
  else if (v.mode === 'W') v.anchor = addDays(v.anchor, 7 * dir);
  else if (v.mode === 'M') v.anchor = addMonths(v.anchor, dir);
  else if (v.mode === 'Y') v.anchor = addMonths(v.anchor, 12 * dir);
  else v.sprint = Math.max(1, v.sprint + dir);
  closePops();
  render();
}
$('#prev').addEventListener('click', () => step(-1));
$('#next').addEventListener('click', () => step(1));

// There is no jump-to-today button and no `+` in the pane: today is the highlighted day in the
// dropdown, and an entry is created where it will live - a cell, the day preview, or a kanban
// column header.

for (const [id, name] of [['#home', 'house'], ['#zoom-btn', 'zoom'], ['#menu-btn', 'menu'],
  ['#day-add', 'plus'], ['#day-close', 'x'], ['#sub-close', 'x'], ['#settings-close', 'x']])
  $(id).append(icon(name));

$('#menu-btn').addEventListener('click', openPanel);
$('#settings-close').addEventListener('click', closePops);

// ---- the dropdown date picker --------------------------------------------------------------
// A month at a time, a 9-year grid, or - in the kanban - a list of sprints.

// The label opens the picker, and that is all it does, in every view and on both platforms. The
// caret existed only because the label's own tap was taken by the zoom; the zoom is a button of
// its own now, so the label is free to be the one thing it was always read as.
function openPicker() {
  if (!$('#picker').hidden) return closePops();
  closePops();
  const [y, m] = partsOf(S.view.anchor);
  pick = S.view.mode === 'K'
    ? { mode: 'sprints', base: Math.max(1, S.view.sprint - 4) }
    : { mode: 'days', y, m: m - 1, base: y - 8 };
  renderPicker();
  openPop($('#picker'), $('#period'), 'right');
}
$('#period').addEventListener('click', openPicker);

// There is no swipe. The label was swiped only because a phone's pane had no `‹` `›` to press;
// they are on its second row now, and a gesture doing what a visible button does is a second
// mechanism for one action. So no sideways gesture does anything, in any view, and nothing has
// to be told apart from a card drag on the board or a scroll in a grid.

$('#pick-title').addEventListener('click', () => {
  if (pick.mode === 'sprints') return;
  pick.mode = pick.mode === 'days' ? 'years' : 'days';
  pick.base = pick.y - 8;
  renderPicker();
});
$('#pick-prev').addEventListener('click', () => pagePicker(-1));
$('#pick-next').addEventListener('click', () => pagePicker(1));

function pagePicker(dir) {
  if (pick.mode === 'years') pick.base += dir * 9;
  else if (pick.mode === 'sprints') pick.base = Math.max(1, pick.base + dir * 9);
  else {
    const m = pick.m + dir;
    pick.y += Math.floor(m / 12);
    pick.m = (m + 12) % 12;
  }
  renderPicker();
}

function renderPicker() {
  const body = $('#pick-body');

  if (pick.mode === 'sprints') {
    $('#pick-label').textContent = 'Sprints';
    body.className = 'pick-body sprints';
    body.replaceChildren(...Array.from({ length: 9 }, (_, i) => {
      const r = sprintRange(pick.base + i, S.model.settings);
      // The sprint today falls in reads `current` and carries the brighter background; the
      // selected one is marked, not renamed, so the two can be the same row.
      const cur = r.n === currentSprint();
      const b = el('button', `pk wide${cur ? ' cur' : ''}${r.n === S.view.sprint ? ' now' : ''}`,
        `${cur ? 'current' : `Sprint ${r.n}`} · ${dayLabel(r.start)} – ${dayLabel(r.end)}`);
      b.type = 'button';
      b.addEventListener('click', () => {
        closePops();
        S.view.sprint = r.n;
        S.view.anchor = r.start;
        render();
      });
      return b;
    }));
    return;
  }

  if (pick.mode === 'years') {
    // 9 years ending with the current one; the arrows page by 9.
    $('#pick-label').textContent = `${pick.base} – ${pick.base + 8}`;
    body.className = 'pick-body years';
    body.replaceChildren(...Array.from({ length: 9 }, (_, i) => {
      const y = pick.base + i;
      const b = el('button', `pk${y === partsOf(S.view.anchor)[0] ? ' now' : ''}`, String(y));
      b.type = 'button';
      b.addEventListener('click', () => { pick = { ...pick, mode: 'days', y }; renderPicker(); });
      return b;
    }));
    return;
  }

  $('#pick-label').textContent =
    new Date(pick.y, pick.m, 1, 12).toLocaleDateString(undefined, { month: 'long', year: 'numeric' });
  body.className = 'pick-body days';
  body.replaceChildren(
    ...weekLetters().map(([n]) => el('span', 'wh', n)),
    ...monthGrid(pick.y, pick.m, S.prefs.weekStart).map(k => {
      const [, mm, dd] = partsOf(k);
      const b = el('button', `pk${mm !== pick.m + 1 ? ' out' : ''}${k === todayKey() ? ' now' : ''}`,
        String(dd));
      b.type = 'button';
      b.addEventListener('click', () => {
        closePops();
        S.view.anchor = k;
        render();
        // Picking a date in a view that cannot show the day's entries in place opens the preview.
        if (S.view.mode === 'Y' || (S.view.mode === 'M' && phone())) openDayPop(k);
      });
      return b;
    }));
}

$('#scrim').addEventListener('click', closePops);
addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  if (!$('#ask').hidden) $('#ask-keep').click();
  else if (!$('#sub').hidden) $('#sub-close').click();
  else if (!$('#popup').hidden) closePopup();
  else closePops();
});
matchMedia('(min-width: 600px)').addEventListener('change', () => { closePops(); render(); });

// ---- sync ----------------------------------------------------------------------------------

function status(text, bad) {
  const s = $('#sync');
  s.textContent = text;
  s.classList.toggle('bad', !!bad);
}

async function showSync() {
  const n = await queuedCount();
  status(n ? `${n} change(s) pending` : 'in sync');
}

// Every write reaches the local mirror first, so the view is already right and the push can run
// behind it. One drain at a time, and failures and conflicts are reported here rather than in
// the popup the user has already left.
let chain = Promise.resolve();
function push(message) {
  chain = chain.then(async () => {
    status('pushing…');
    try {
      const r = await drain(message);
      if (r.conflicts?.length)
        status(`${r.conflicts.length} change(s) kept beside the remote version as .conflict files — review them`, true);
      else await showSync();
    } catch (err) {
      status(`not pushed: ${err.message}`, true);
    }
  });
}

async function refresh() {
  if (await queuedCount()) return showSync();
  status('checking…');
  try {
    const r = await pull();                    // whole repo: the mirror and the ETag are shared
    if (!r.unchanged) { S.model = await loadModel(); render(); }
    status(r.empty ? 'repo is empty' : r.unchanged ? 'in sync' : `in sync — ${r.changed} file(s) updated`);
  } catch (err) {
    status(err.message, true);
  }
}

// ---- boot ----------------------------------------------------------------------------------

S.render = render;
S.status = status;
S.push = push;
S.reload = loadModel;
wireView();

const minePrefs = await loadPrefs();
applyTheme(minePrefs.theme);

if (!await getConfig()) {
  $('#needs-setup').hidden = false;
} else {
  $('#cal').hidden = false;
  S.prefs = {
    ...S.prefs, ...minePrefs,
    weekStart: (await getKV('calendar.weekStart')) ?? 1,
    showWeeks: !!(await getKV('calendar.showWeeks')),
    confirmDiscard: (await getKV('calendar.confirmDiscard')) ?? true,
    timeZone: (await getKV('calendar.timeZone')) || '',
    boardOrientation: (await getKV('calendar.boardOrientation')) || 'horz'
  };
  setZone(S.prefs.timeZone);
  S.hidden = new Set(await getKV('calendar.hiddenGroups') || []);
  S.model = await loadModel();
  S.view.anchor = todayKey();
  S.view.sprint = currentSprint();
  render();
  await refresh();
  addEventListener('focus', refresh);
}

// The panel behind the hamburger: the filter at the top, the settings below it, under a heading
// each. They are one panel because they are one errand - both are things you adjust about the
// view in front of you and then leave alone, and two buttons a thumb's width apart asked which
// of the two a given switch was before you could reach it. Merging them also freed the slot the
// zoom took, which is what keeps the pane at four controls.
//
// Everything here is stored on the device except the groups, the sprint length and the first
// sprint date: those three are data and live in the repo, because the sprint a task belongs to
// is derived from them and two devices that disagreed would put the same card in different
// sprints. Theme and date format are Mine-wide, not the calendar's.
//
// Every row is two halves - the label on the left, its control on the right - so the controls
// line up in one column. That alignment is the whole of what the panel was missing: a select, a
// text box, a checkbox and a date field each started wherever its own label happened to end.
// The groups are behind a button rather than listed, because a list grew with the repo and
// pushed the nine settings that never change below the fold.
import { setKV } from '../shared/store.js';
import { saveSettings, setZone, getZone } from './data.js';
import { THEMES, DATE_FORMATS, applyTheme, setPref } from '../shared/prefs.js';
import { openGroups } from './popup.js';
import { S, $, el, closePops, openCentred, colorOf, labelOf } from './ui.js';

export function openPanel() {
  closePops();
  build();
  renderFilter();
  openCentred($('#settings-panel'));
}

// ---- the filter ----------------------------------------------------------------------------
// A view filter, remembered per device. Groups are named and coloured below, in the settings
// section's `edit groups`, not here.

function groupNames() {
  const names = new Set(Object.keys(S.model.groups));
  let ungrouped = false;
  for (const e of [...S.model.dated, ...S.model.rules]) {
    if (e.data.group) names.add(e.data.group); else ungrouped = true;
  }
  const out = [...names].sort().map(n => [n, labelOf(n)]);
  if (ungrouped) out.push(['', 'no group']);
  return out;
}

// Groups are a dropdown rather than a list: one row saying how many are on, which opens to the
// same checkboxes. Folded is how it starts, and that is load bearing twice over now - a repo
// with twenty groups would otherwise give the panel a filter taller than the screen and push
// the nine settings rows below the fold.
let groupsOpen = false;

export function renderFilter() {
  const names = groupNames();
  const on = names.filter(([n]) => !S.hidden.has(n)).length;
  const drop = el('button', 'gdrop', `groups · ${on} of ${names.length} ${groupsOpen ? '▴' : '▾'}`);
  drop.type = 'button';
  drop.setAttribute('aria-expanded', String(groupsOpen));
  drop.addEventListener('click', () => { groupsOpen = !groupsOpen; renderFilter(); });
  const kids = [drop];

  if (groupsOpen) for (const [name, label] of names) {
    const lab = el('label', 'glab');
    const box = el('input');
    box.type = 'checkbox';
    box.checked = !S.hidden.has(name);
    box.addEventListener('change', async () => {
      if (box.checked) S.hidden.delete(name); else S.hidden.add(name);
      await setKV('calendar.hiddenGroups', [...S.hidden]);
      S.render();
    });
    const sw = el('span', 'swatch');
    sw.style.background = colorOf(name);
    lab.append(box, sw, el('span', '', label || name));
    kids.push(lab);
  }

  // Importance and assignee narrow the board, where a sprint can hold more cards than fit. One
  // switch, now that importance is a yes or no rather than three tiers to pick between.
  if (S.view.mode === 'K') {
    const chip = el('button', `chip${S.kfilter.importantOnly ? ' on' : ''}`, '!');
    chip.type = 'button';
    chip.title = 'Important only';
    chip.setAttribute('aria-label', 'Important only');
    chip.setAttribute('aria-pressed', String(S.kfilter.importantOnly));
    chip.addEventListener('click', () => {
      S.kfilter.importantOnly = !S.kfilter.importantOnly;
      S.render();
    });
    kids.push(row('Important only', chip));

    const people = [...new Set([...S.model.dated, ...S.model.rules]
      .flatMap(e => [].concat(e.data.participants ?? []).map(String)))].sort();
    kids.push(row('Assignee', choose([['', 'anyone'], ...people.map(p => [p, p])],
      S.kfilter.assignee, v => { S.kfilter.assignee = v; S.render(); })));
  }

  $('#filter-body').replaceChildren(...kids);
}

// Nine rows and nothing after them: there is no paragraph explaining what is stored where,
// because that belongs in REQUIREMENTS.md and not on a panel opened to change the theme.
function build() {
  $('#settings-body').replaceChildren(
    row('Groups', groupsButton()),
    row('Start week on', choose([[1, 'Monday'], [0, 'Sunday']], S.prefs.weekStart,
      v => local('weekStart', Number(v)))),
    row('Time zone', zoneField()),
    row('Date format', choose(DATE_FORMATS.map(f => [f, f]), S.prefs.dateFormat,
      v => mine('dateFormat', v))),
    row('Calendar weeks', toggle(S.prefs.showWeeks, v => local('showWeeks', v))),
    // The way back on. A prompt silenced from inside itself needs a row that can restore it,
    // because nothing in Mine may be switched off from a place that cannot switch it back on.
    row('Confirm discard', toggle(S.prefs.confirmDiscard, v => local('confirmDiscard', v))),
    row('Sprint length', numberField(S.model.settings.interval, 1,
      v => sprints({ interval: v })), 'weeks'),
    row('First sprint', dateField(S.model.settings.anchor, v => sprints({ anchor: v }))),
    row('Theme', choose(THEMES.map(t => [t, t]), S.prefs.theme, v => mine('theme', v)))
  );
}

// ---- rows ----------------------------------------------------------------------------------

// Two halves. A unit shares the right half with its control rather than dropping below it,
// which is the one place a row would otherwise go ragged again.
function row(label, control, suffix) {
  const r = el('div', 'srow');
  r.append(el('span', 'slab', label));
  if (!suffix) r.append(control);
  else {
    const v = el('div', 'sval');
    v.append(control, el('span', 'ssuf', suffix));
    r.append(v);
  }
  return r;
}

// The same popup the entry popup's category field opens, in its manage-only form: one place
// where a group is named or coloured, so there is no second list to keep in step.
function groupsButton() {
  const b = el('button', 'link', 'edit groups');
  b.type = 'button';
  b.id = 'edit-groups';
  b.addEventListener('click', openGroups);
  return b;
}

function choose(options, current, onChange) {
  const s = el('select');
  for (const [v, text] of options) {
    const o = el('option', '', text);
    o.value = String(v);
    if (String(v) === String(current)) o.selected = true;
    s.append(o);
  }
  s.addEventListener('change', () => onChange(s.value));
  return s;
}

function toggle(current, onChange) {
  const i = el('input');
  i.type = 'checkbox';
  i.checked = !!current;
  i.addEventListener('change', () => onChange(i.checked));
  return i;
}

function numberField(current, min, onChange) {
  const i = el('input');
  i.type = 'number';
  i.min = String(min);
  i.value = String(current);
  i.addEventListener('change', () => {
    const n = Number(i.value);
    if (Number.isInteger(n) && n >= min) onChange(n); else i.value = String(current);
  });
  return i;
}

function dateField(current, onChange) {
  const i = el('input');
  i.type = 'date';
  i.value = current;
  i.addEventListener('change', () => { if (i.value) onChange(i.value); });
  return i;
}

// A zone name, not an offset: a plain UTC+1 is an hour wrong for half the year in any zone with
// daylight saving. Empty means the device's own.
function zoneField() {
  const i = el('input');
  i.value = S.prefs.timeZone;
  i.placeholder = getZone();
  i.autocapitalize = 'off';
  i.spellcheck = false;
  i.addEventListener('change', () => {
    const typed = i.value.trim();
    const chosen = setZone(typed);
    if (typed && chosen !== typed) {
      i.value = '';
      S.status(`"${typed}" is not a zone name — using ${chosen}.`, true);
    }
    local('timeZone', i.value.trim());
    i.placeholder = getZone();
  });
  return i;
}

// ---- writes --------------------------------------------------------------------------------

async function sprints(patch) {
  await saveSettings({ ...S.model.settings, ...patch });
  S.model = await S.reload();
  build();
  S.render();
  S.push('calendar: sprint settings');
}

async function local(key, value) {
  S.prefs[key] = value;
  await setKV(`calendar.${key}`, value);
  S.render();
}

// A re-render redraws the filter, because the board's two controls are only in it on the board.
// `S.render()` calls back into renderFilter, so this file does not have to.

async function mine(key, value) {
  S.prefs[key] = value;
  await setPref(key, value);
  if (key === 'theme') applyTheme(value);
  S.render();
}

// The bits every view needs: DOM helpers, the icon set, and the mutable state.
//
// State lives in one object rather than being threaded through every function, and `S.render`
// / `S.status` / `S.push` are slots the shell fills in, so a view can ask for a redraw or a
// background push without importing app.js back.
import {
  todayKey, DEFAULT_ANCHOR, groupColor, groupLabel, monthGrid, weekStartOf, addDays, partsOf,
  dowOf, sprintRange, sprintOf
} from './data.js';
import { formatDate, weekdayName } from '../shared/prefs.js';

export const $ = s => document.querySelector(s);
export const el = (tag, cls, text) => {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
};
export const phone = () => !matchMedia('(min-width: 600px)').matches;

export const S = {
  model: { groups: {}, dated: [], rules: [], overrides: new Map(),
           settings: { anchor: DEFAULT_ANCHOR, interval: 2 } },
  view: { mode: 'M', anchor: todayKey(), sprint: 1, col: 0 },
  prefs: { weekStart: 1, showWeeks: false, confirmDiscard: true, timeZone: '',
           theme: 'system', dateFormat: 'auto', boardOrientation: 'horz' },
  hidden: new Set(),                 // group names switched off in the filter
  kfilter: { importantOnly: false, assignee: '' },   // kanban only
  visible: new Map(),                // occurrence key -> occurrence, for what is on screen
  render: () => {},
  status: () => {},
  push: () => {},
  reload: async () => S.model
};

// The kanban's column colours. In ui.js rather than kanban.js because the entry popup's stage
// button carries the same three, and one table is the only way they cannot drift apart.
export const STAGE_COLOR = { todo: '#c0392b', doing: '#e0a500', done: '#27ae60' };

export const colorOf = g => groupColor(S.model.groups, g);
export const labelOf = g => groupLabel(S.model.groups, g);
export const dayLabel = key => formatDate(key, S.prefs.dateFormat);
export const longDayLabel = key => `${weekdayName(key)}, ${formatDate(key, S.prefs.dateFormat)}`;

// Text on a group-coloured background. Luminance rather than a fixed colour, because the
// groups are user-chosen and a light one would otherwise carry white text.
export function inkOn(hex) {
  const h = String(hex).replace('#', '');
  const n = h.length === 3 ? h.split('').map(c => c + c).join('') : h.slice(0, 6);
  const [r, g, b] = [0, 2, 4].map(i => parseInt(n.slice(i, i + 2), 16) / 255 || 0);
  const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return lum > 0.6 ? '#1b1f24' : '#fff';
}

// The inclusive day range the current view shows.
export function viewRange() {
  const { mode, anchor, sprint } = S.view;
  if (mode === 'D') return [anchor, anchor];
  if (mode === 'W') { const a = weekStartOf(anchor, S.prefs.weekStart); return [a, addDays(a, 6)]; }
  if (mode === 'M') {
    const [y, m] = partsOf(anchor);
    const g = monthGrid(y, m - 1, S.prefs.weekStart);
    return [g[0], g[g.length - 1]];
  }
  if (mode === 'Y') { const [y] = partsOf(anchor); return [`${y}-01-01`, `${y}-12-31`]; }
  const r = sprintRange(sprint, S.model.settings);
  return [r.start, r.end];
}

