// Escape unwinds one layer at a time: a field's popup, then an inline row, then the popup. The
// shell calls this rather than closePopup, so Escape in an open field does not throw away the
// edit the field is part of.
export function escapeEntry() {
  if (popped !== null) closeFieldPop();
  else if (active) closeRow();
  else closePopup();
}

